ALLOWED = {
    "New": {"Open", "Rejected"},
    "Open": {"Fixed", "Deferred"},
    "Fixed": {"Verified", "Reopened"},
    "Reopened": {"Fixed"},
    "Deferred": {"Open"},
    "Verified": {"Closed"},
}

def check(history):
    for a, b in zip(history, history[1:]):
        if b not in ALLOWED.get(a, set()):
            return f"막힘: {a} → {b}"
    return "OK"

print(check(["New", "Open", "Fixed", "Reopened", "Fixed", "Verified", "Closed"]))  # OK
print(check(["New", "Open", "Closed"]))  # 막힘: Open → Closed
